def borrow_book(library, isbn):
    book = library.get(isbn)
    if book is None:
        return "Error: Book not found"
    if book["copies_available"] <= 0:
        return f"Error: No copies of '{book['title']}' are currently available"
    book["copies_available"] -= 1
    return f"Borrowed '{book['title']}'. Copies left: {book['copies_available']}"
def return_book(library, isbn):
    book = library.get(isbn)
    if book is None:
        return "Error: Book not found"
    if book["copies_available"] >= book["copies_total"]:
        return "Error: All copies are already in the library"
    book["copies_available"] += 1
    return f"Returned '{book['title']}'. Copies left: {book['copies_available']}"
def search_by_author(library, author):
    target = author.lower()
    matches = [b["title"] for b in library.values() if target in b["author"].lower()]
    return sorted(matches)
