def total_revenue(products):
    return sum(p["price"] * p["quantity"] for p in products)
def top_selling(products):
    return max(products, key=lambda p: p["quantity"])["product"] if products else None
def rated_products(products, threshold):
    selected = filter(lambda p: p["rating"] >= threshold, products)
    return list(map(lambda p: p["product"], selected))
def category_revenue(products):
    totals = {}
    for p in products:
        category = p["category"]
        value = p["price"] * p["quantity"]
        totals[category] = totals.get(category, 0) + value
    return totals
